"""Consume a golden freeze generated by unmodified pinned ops/ACL source code."""
from copy import deepcopy
import gzip
import json

import pytest

from qb_data.acl_protocol import ArmSpec, digest, prepare
from scripts.acl_upstream_conformance import FIXTURE, JANE_REVISION

CROSSWALK = {"calibration":"train","selection":"val","test":"test"}
GOLDEN = "3f820bf5f6a92b551b66e1a02155a8bdde9473d9e89cd20d834ea7c89ab5921f"


def fixture():
    with gzip.open(FIXTURE, "rb") as fp:
        result = json.load(fp)
    assert result["upstream_revision"] == JANE_REVISION and digest(result) == GOLDEN
    assert result["classification"] == "synthetic schema conformance"
    dataset, donors = result["dataset"], result["reservoir"]
    assert dataset["source"]["human_review"] is False
    classes = {q["source"]["canonical_answer"]:q["answer"]["accepted"] for q in dataset["questions"]}
    classes.update({d["canonical_answer"]:d["aliases"] for d in donors})
    aliases = {"version":"fixture-only", "reviewer":"synthetic fixture mapping from explicit labels",
               "classes":classes}
    return dataset, donors, aliases


@pytest.mark.parametrize("condition", ["same_category_pool","independent_pool"])
def test_upstream_frozen_baseline_preserves_source_order_gold_and_donor_ids(condition):
    dataset, donors, aliases = fixture()
    spec = ArmSpec.from_dict(dict(version=1, k=4, menu="baseline", seed=1,
                                  baseline_condition=condition,reward={"arm":"baseline"}))
    p = prepare(spec, dataset, aliases, reservoir=donors, split_roles=CROSSWALK)
    sources = {q["qid"]:q for q in dataset["questions"]}
    assert set(q.gold_index for rows in p.questions.values() for q in rows) == set(range(4))
    for split, rows in p.questions.items():
        for q in rows:
            real = sources[q.qid]
            assert split == CROSSWALK[real["split"]] and p.groups[q.qid] == real["group_id"]
            assert q.cumulative_prefixes == [i["text"] for i in real["prefixes"]]
            assert len(q.cumulative_prefixes) == 10
            menu = next(m for m in real["menus"] if m["condition"] == condition)
            assert q.options == [o["text"] for o in menu["options"]]
            assert menu["options"][q.gold_index]["id"] == menu["gold_option_id"]
            ids = [[s] for s in menu["provenance"]["candidate_source_ids"]]
            ids.insert(q.gold_index, [])
            assert list(map(list,p.menus[q.qid]["source_ids"])) == ids


def test_upstream_heldout_retrieval_has_only_separate_reference_donors():
    dataset, donors, aliases = fixture()
    spec = ArmSpec.from_dict(dict(version=1,k=4,seed=1,menu="prefix_tfidf",reward={"arm":"baseline"}))
    prepared = prepare(spec,dataset,aliases,reservoir=donors,split_roles=CROSSWALK)
    eligible = {r["source"]["_id"] for r in donors}
    target_ids = {sid for q in dataset["questions"] for sid in q["source"]["component_source_ids"]}
    assert len(eligible) == 6 and eligible.isdisjoint(target_ids)
    for role in ("val","test"):
        for q in prepared.questions[role]:
            sources = prepared.menus[q.qid]["source_ids"]
            distractors = [set(s) for i,s in enumerate(sources) if i != q.gold_index]
            assert len(distractors) == 3 and all(ids and ids <= eligible for ids in distractors)
            assert not set().union(*distractors) & target_ids
    corrupted = deepcopy(donors)
    corrupted[0]["component_source_ids"].append(next(iter(target_ids)))
    with pytest.raises(ValueError,match="overlap"):
        prepare(spec,dataset,aliases,reservoir=corrupted,split_roles=CROSSWALK)
